#!/bin/sh
# Homelab-Zentrale: adds this server to the hub in one step.
#
#   curl -fsSL @@HZ_HUB_ORIGIN@@/install.sh | sudo sh -s -- <code>
#
# Generated by the core. The script is the same for every server and contains
# no secret: the one-time code from "Server hinzufügen" is passed as argument
# and swapped for an enrollment token over the tailnet.
#
# What it does:
#   1. checks root, the code format, Docker (with Compose v2), Tailscale and curl,
#   2. swaps the code for the agent settings (POST @@HZ_EXCHANGE_PATH@@),
#   3. writes /etc/homelab-agent/agent.env (mode 0600, outside /opt/homelab so no
#      agent action can rewrite it) and the compose file, like deploy/install-agent.sh,
#   4. pulls the agent image and starts the agent.
# The agent opens no port; it connects out to the hub over Tailscale.
# The token is never printed.
set -eu
# Byte-wise character classes in case/grep/tr, whatever the caller's locale.
LC_ALL=C
export LC_ALL

HUB='@@HZ_HUB_ORIGIN@@'
CODE_RE='@@HZ_CODE_RE@@'
EXCHANGE_PATH='@@HZ_EXCHANGE_PATH@@'
# Fixed paths. Only a core in NODE_ENV=test renders these as overridable
# (HZ_TEST_CONF_DIR / HZ_TEST_HOMELAB_DIR) for its integration test.
CONF_DIR=@@HZ_CONF_DIR@@
HOMELAB_DIR=@@HZ_HOMELAB_DIR@@
CONTAINER=homelab-agent

die() {
  printf 'Fehler: %s\n' "$*" >&2
  exit 1
}

[ "$#" -eq 1 ] || die "Aufruf: curl -fsSL $HUB/install.sh | sudo sh -s -- <code>"
code=$1
# Whole-argument check first: grep below matches per line, so a multi-line
# argument with a valid first line must never get that far.
case "$code" in
  '' | *[!A-Za-z0-9-]*) die "Der Code hat ein ungültiges Format (XXXX-XXXX)." ;;
esac
[ "${#code}" -le 9 ] || die "Der Code hat ein ungültiges Format (XXXX-XXXX)."
printf '%s\n' "$code" | grep -Eq "$CODE_RE" || die "Der Code hat ein ungültiges Format (XXXX-XXXX)."
[ "$(id -u)" -eq 0 ] || die "bitte als root ausführen (sudo)"

# --- requirements -------------------------------------------------------------
command -v curl >/dev/null 2>&1 || die "curl fehlt"
command -v docker >/dev/null 2>&1 || die "Docker fehlt (https://docs.docker.com/engine/install/)"
docker info >/dev/null 2>&1 || die "der Docker-Dienst läuft nicht"
docker compose version >/dev/null 2>&1 || die "Docker Compose v2 fehlt (Paket docker-compose-plugin)"
command -v tailscale >/dev/null 2>&1 || die "Tailscale fehlt (https://tailscale.com/download/linux)"
tailscale status >/dev/null 2>&1 || die "Tailscale ist nicht verbunden (tailscale up)"

if [ -f "$CONF_DIR/agent.env" ] || docker inspect "$CONTAINER" >/dev/null 2>&1; then
  die "Auf diesem Server ist schon ein Agent eingerichtet. Zum Neu-Einrichten erst 'cd $CONF_DIR && docker compose down' ausführen und $CONF_DIR/agent.env löschen."
fi

# --- exchange -------------------------------------------------------------------
install -d -m 0755 "$HOMELAB_DIR"
install -d -m 0700 "$CONF_DIR"
umask 077
# Temp files with the exchange answer and the half-written agent.env are
# removed on every exit (also abort by set -e or a signal) until they are moved.
resp=''
tmp=''
cleanup() {
  [ -z "$resp" ] || rm -f "$resp"
  [ -z "$tmp" ] || rm -f "$tmp"
}
trap cleanup EXIT
trap 'cleanup; exit 1' INT TERM HUP
resp=$(mktemp "$CONF_DIR/.onboarding.XXXXXX")

case "$HUB" in
  https://*) proto='=https' ;;
  *) proto='=http' ;;
esac
code=$(printf '%s' "$code" | tr 'abcdefghijklmnopqrstuvwxyz' 'ABCDEFGHIJKLMNOPQRSTUVWXYZ')
# The code goes over stdin, so it is not in curl's arguments (ps).
status=$(printf '{"code":"%s"}' "$code" | curl -sS --proto "$proto" --max-time 30 \
  -o "$resp" -w '%{http_code}' -X POST -H 'Content-Type: application/json' \
  --data-binary @- "$HUB$EXCHANGE_PATH") || die "Die Zentrale ist nicht erreichbar ($HUB)."
unset code
case "$status" in
  200) ;;
  429) die "Zu viele Versuche. Bitte später erneut versuchen." ;;
  *) die "Code ungültig oder abgelaufen. Bitte in der Zentrale einen neuen Code erzeugen." ;;
esac

# One KEY=value line per key, each with a strict pattern (no eval, no sourcing).
env_value() {
  n=$(grep -c "^$1=" "$resp" || true)
  [ "$n" = 1 ] || die "Unerwartete Antwort der Zentrale."
  v=$(sed -n "s/^$1=//p" "$resp")
  printf '%s\n' "$v" | grep -Eq "^($2)\$" || die "Unerwartete Antwort der Zentrale."
  printf '%s' "$v"
}
core_url=$(env_value HZ_CORE_URL 'wss://[A-Za-z0-9.-]+(:[0-9]{1,5})?/agent|ws://127\.0\.0\.1:[0-9]{1,5}/agent')
name=$(env_value HZ_AGENT_NAME '[a-z0-9][a-z0-9-]{0,62}')
token=$(env_value HZ_AGENT_TOKEN '[A-Za-z0-9_-]{22,128}')
image=$(env_value HZ_AGENT_IMAGE '[a-z0-9][a-z0-9._/:@-]{0,254}')
rm -f "$resp"
resp=''

# --- files --------------------------------------------------------------------
tmp=$(mktemp "$CONF_DIR/.agent.env.XXXXXX")
{
  echo "# Homelab-Zentrale agent. Written by install.sh. Contains a secret: keep 0600."
  printf 'HZ_CORE_URL=%s\n' "$core_url"
  printf 'HZ_AGENT_NAME=%s\n' "$name"
  printf 'HZ_AGENT_TOKEN=%s\n' "$token"
  printf 'HZ_AGENT_ALLOW_TERMINAL=0\n'
} >"$tmp"
unset token
chmod 0600 "$tmp"
mv -f "$tmp" "$CONF_DIR/agent.env"
tmp=''

# Same service as deploy/docker-compose.agent.yml (see the comments there for why
# each right is needed). Quoted heredoc: nothing in it is expanded by the shell.
cat >"$CONF_DIR/docker-compose.yml" <<'COMPOSE'
name: homelab-agent

services:
  agent:
    image: ${HZ_AGENT_IMAGE:-ghcr.io/puffybooy/homelab-agent:latest}
    container_name: homelab-agent
    restart: unless-stopped
    labels:
      hz.role: agent
    env_file:
      - path: ${HZ_AGENT_ENV_FILE:-/etc/homelab-agent/agent.env}
        required: false
    environment:
      HZ_AGENT_DATA: /data
      HZ_AGENT_HOST_EXEC: nsenter
      HZ_AGENT_HOST_PROC: /host/proc
      HZ_AGENT_HOST_ROOT: /host/proc/1/root
    user: '0:0'
    pid: host
    network_mode: host
    read_only: true
    tmpfs:
      - /tmp
    cap_drop:
      - ALL
    cap_add:
      - SYS_ADMIN
      - SYS_PTRACE
      - SYS_CHROOT
      - DAC_READ_SEARCH
      - DAC_OVERRIDE
      - CHOWN
      - FOWNER
      - FSETID
      - SETUID
      - SETGID
      - NET_RAW
    security_opt:
      - no-new-privileges:true
      - apparmor=unconfined
    volumes:
      - /var/run/docker.sock:/var/run/docker.sock
      - /proc:/host/proc:ro
      - /sys:/host/sys:ro
      - type: bind
        source: /opt/homelab
        target: /opt/homelab
        bind:
          create_host_path: true
      - agent-data:/data
    logging:
      driver: json-file
      options:
        max-size: 10m
        max-file: '3'

volumes:
  agent-data:
COMPOSE
chmod 0644 "$CONF_DIR/docker-compose.yml"

# Interpolation variables for compose (no secrets here).
printf 'HZ_AGENT_IMAGE=%s\nHZ_AGENT_ENV_FILE=%s\n' "$image" "$CONF_DIR/agent.env" >"$CONF_DIR/.env"
chmod 0644 "$CONF_DIR/.env"

# --- start --------------------------------------------------------------------
cd "$CONF_DIR"
echo "Lade $image ..."
# The code is used up now: on failure the agent.env must go before a new try.
start_failed() {
  die "Der Agent konnte nicht geladen oder gestartet werden (siehe oben). Bitte $CONF_DIR/agent.env löschen und mit einem neuen Code aus der Zentrale erneut versuchen."
}
docker compose pull agent || start_failed
docker compose up -d --no-build --force-recreate agent || start_failed

echo
echo "Agent \"$name\" läuft. Die Zentrale zeigt gleich \"verbunden\"."
echo "Logs:      docker logs -f $CONTAINER"
echo "Neustart:  cd $CONF_DIR && docker compose up -d"
echo "Entfernen: cd $CONF_DIR && docker compose down -v"
